-- Schema-only production snapshot for isolated synthetic tests. NO production data.
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE public.admin_access_logs (id uuid DEFAULT gen_random_uuid() NOT NULL, created_at timestamp with time zone DEFAULT now(), email text NOT NULL, action text NOT NULL, details text, ip_address text, user_agent text);
CREATE TABLE public.authorized_admins (id uuid DEFAULT gen_random_uuid() NOT NULL, email text NOT NULL, nombre text, rol text DEFAULT 'admin'::text, created_at timestamp with time zone DEFAULT now(), updated_at timestamp with time zone DEFAULT now());
CREATE TABLE public.domos (id uuid DEFAULT gen_random_uuid() NOT NULL, nombre text NOT NULL, capacidad integer NOT NULL, activo boolean DEFAULT true, created_at timestamp without time zone DEFAULT now(), airbnb_ical_url text);
CREATE TABLE public.reserva_cambios (id uuid DEFAULT gen_random_uuid() NOT NULL, reserva_id uuid NOT NULL, campo text NOT NULL, valor_anterior text, valor_nuevo text, admin_email text, snapshot jsonb, created_at timestamp with time zone DEFAULT now());
CREATE TABLE public.reserva_cobros (id uuid DEFAULT gen_random_uuid() NOT NULL, reserva_id uuid NOT NULL, tipo text NOT NULL, concepto text NOT NULL, cantidad integer DEFAULT 1 NOT NULL, precio_unitario integer NOT NULL, total integer NOT NULL, es_cortesia boolean DEFAULT false NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE public.reserva_servicios (id uuid DEFAULT gen_random_uuid() NOT NULL, reserva_id uuid, servicio_id uuid, cantidad integer DEFAULT 1, precio_unitario integer NOT NULL, total integer NOT NULL, created_at timestamp with time zone DEFAULT now(), es_cortesia boolean DEFAULT false);
CREATE TABLE public.reservas (id uuid DEFAULT gen_random_uuid() NOT NULL, uid text DEFAULT (gen_random_uuid())::text, fecha_inicio date NOT NULL, fecha_fin date NOT NULL, resumen text, descripcion text, fuente text DEFAULT 'airbnb'::text, creado_en timestamp with time zone DEFAULT now(), actualizado_en timestamp with time zone DEFAULT now(), adultos integer DEFAULT 2, domo_id uuid, estado text DEFAULT 'confirmada'::text, expires_at timestamp with time zone, total numeric DEFAULT 0, apellido text, nombre text, email text, telefono text, cliente_id uuid, is_vip_booking boolean DEFAULT false, num_huespedes integer, ninos integer DEFAULT 0, mascotas boolean DEFAULT false, notas text, requerimientos_especiales text, metodo_pago text, numero_transaccion text, confirmado_por text, check_in_time time without time zone, check_out_time time without time zone, precio_noche numeric, descuento numeric DEFAULT 0, impuestos numeric DEFAULT 0, notas_internas text, fuente_reserva text, updated_at timestamp with time zone DEFAULT now(), deleted_at timestamp with time zone, created_by text, updated_by text, version integer DEFAULT 1, source_system text, external_id text, is_tentative boolean DEFAULT false, cancellation_reason text, cancelled_at timestamp with time zone, rut text, pais text, codigo_postal text, provincia text, piso text, numero_casa text, departamento text, tipo_alojamiento text, comentarios_cliente text, referencia_externa text, pagado_at timestamp with time zone, checkout_realizado boolean DEFAULT false, ocupacion_final integer, rating_cliente numeric, comentario_experiencia text, follow_up_enviado boolean DEFAULT false, campaign_source text, medium text, utm_campaign text, utm_medium text, utm_source text, created_at timestamp with time zone DEFAULT now(), payment_intent_id text, metodo_pago_inicial text, comprobante_url text, monto_pagado numeric DEFAULT 0, metadata jsonb DEFAULT '{}'::jsonb, utm_content text, utm_term text, enviar_confirmacion boolean DEFAULT true, acompanantes text, tipo_documento character varying(20) DEFAULT 'boleta'::character varying, sincronizar_calendario boolean DEFAULT true, airbnb_uid text, gclid text, fbclid text, click_id_captured_at timestamp with time zone, pago_ultimo_error text, pago_intentos integer DEFAULT 0, ga_client_id text, origen_marketing text, detalle_origen text, gbraid text, wbraid text, msclkid text, click_id_tipo text, click_id text, pago_detalle jsonb);
CREATE TABLE public.servicios (id uuid DEFAULT gen_random_uuid() NOT NULL, nombre text NOT NULL, descripcion text, precio integer NOT NULL, multiplicador_noches boolean DEFAULT false, multiplicador_personas boolean DEFAULT false, activo boolean DEFAULT true, image_url text, created_at timestamp with time zone DEFAULT now());
ALTER TABLE domos ADD CONSTRAINT domos_pkey PRIMARY KEY (id);
ALTER TABLE servicios ADD CONSTRAINT servicios_pkey PRIMARY KEY (id);
ALTER TABLE reserva_servicios ADD CONSTRAINT reserva_servicios_pkey PRIMARY KEY (id);
ALTER TABLE authorized_admins ADD CONSTRAINT authorized_admins_email_key UNIQUE (email);
