ALTER TABLE admin_access_logs ADD CONSTRAINT admin_access_logs_pkey PRIMARY KEY (id);
ALTER TABLE reservas ADD CONSTRAINT no_double_booking EXCLUDE USING gist (domo_id WITH =, daterange(fecha_inicio, fecha_fin) WITH &&) WHERE (((deleted_at IS NULL) AND (estado = ANY (ARRAY['pagado'::text, 'confirmado'::text, 'pendiente'::text, 'pending_transfer_confirmation'::text, 'bloqueado'::text])) AND (fecha_fin >= '2026-06-09'::date)));
ALTER TABLE reservas ADD CONSTRAINT reservas_airbnb_uid_key UNIQUE (airbnb_uid);
ALTER TABLE reservas ADD CONSTRAINT reservas_click_id_tipo_check CHECK (((click_id_tipo IS NULL) OR (click_id_tipo = ANY (ARRAY['gclid'::text, 'gbraid'::text, 'wbraid'::text, 'fbclid'::text, 'msclkid'::text, 'otro'::text])))) NOT VALID;
ALTER TABLE reservas ADD CONSTRAINT reservas_origen_marketing_check CHECK (((origen_marketing IS NULL) OR (origen_marketing = ANY (ARRAY['whatsapp'::text, 'instagram'::text, 'google_organico'::text, 'google_ads'::text, 'referido'::text, 'otro'::text, 'desconocido'::text])))) NOT VALID;
ALTER TABLE reservas ADD CONSTRAINT reservas_payment_intent_id_key UNIQUE (payment_intent_id);
ALTER TABLE reservas ADD CONSTRAINT reservas_pkey PRIMARY KEY (id);
ALTER TABLE reservas ADD CONSTRAINT reservas_tipo_documento_check CHECK (((tipo_documento)::text = ANY ((ARRAY['boleta'::character varying, 'factura'::character varying])::text[])));
ALTER TABLE reservas ADD CONSTRAINT reservas_uid_key UNIQUE (uid);
ALTER TABLE reserva_cobros ADD CONSTRAINT reserva_cobros_pkey PRIMARY KEY (id);
ALTER TABLE reserva_cobros ADD CONSTRAINT reserva_cobros_tipo_check CHECK ((tipo = ANY (ARRAY['hospedaje'::text, 'extra'::text, 'descuento'::text])));
ALTER TABLE reserva_cambios ADD CONSTRAINT reserva_cambios_pkey PRIMARY KEY (id);
ALTER TABLE reserva_servicios ADD CONSTRAINT reserva_servicios_reserva_id_fkey FOREIGN KEY (reserva_id) REFERENCES reservas(id) ON DELETE CASCADE;
ALTER TABLE reserva_servicios ADD CONSTRAINT reserva_servicios_servicio_id_fkey FOREIGN KEY (servicio_id) REFERENCES servicios(id);
ALTER TABLE reservas ADD CONSTRAINT reservas_domo_id_fkey FOREIGN KEY (domo_id) REFERENCES domos(id) ON DELETE CASCADE;
ALTER TABLE reserva_cobros ADD CONSTRAINT reserva_cobros_reserva_id_fkey FOREIGN KEY (reserva_id) REFERENCES reservas(id) ON DELETE CASCADE;
ALTER TABLE reserva_cambios ADD CONSTRAINT reserva_cambios_reserva_id_fkey FOREIGN KEY (reserva_id) REFERENCES reservas(id) ON DELETE CASCADE;
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
